public bool IsMatch(string s, string p)
{
    int m = s.Length, n = p.Length;
    bool[] prev = new bool[n + 1];
    prev[0] = true;
    for (int j = 1; j <= n; j++)
        if (p[j - 1] == '*')
            prev[j] = prev[j - 2];
    for (int i = 1; i <= m; i++)
    {
        bool[] curr = new bool[n + 1];
        for (int j = 1; j <= n; j++)
        {
            if (p[j - 1] == '*')
                curr[j] = curr[j - 2] || (prev[j] && (p[j - 2] == '.' || p[j - 2] == s[i - 1]));
            else if (p[j - 1] == '.' || p[j - 1] == s[i - 1])
                curr[j] = prev[j - 1];
        }
        prev = curr;
    }
    return prev[n];
}
